#include <cstdio>
#include <queue>
#include <vector>
using namespace std;

struct Node {
    int v;
    int step;
};

int BFS(int n) {
    if (n < 0) return -1;

    queue<Node> q;
    vector<bool> visited(n + 1, false);

    q.push({0, 0});
    visited[0] = true;

    while (!q.empty()) {
        Node current = q.front();
        q.pop();

        if (current.v == n) return current.step;

        for (int i = 1; i <= 5; ++i) {
            int next = current.v + i;
            if (next <= n && !visited[next]) {
                visited[next] = true;
                q.push({next, current.step + 1});
            }
        }
    }

    return -1;
}

int main() {
    int x;
    scanf("%d", &x);
    printf("%d\n", BFS(x));
    return 0;
}

